(function(g){'use strict';var KEY='hooklab_corpus_stat_store_v0_1';function load(){try{return JSON.parse(localStorage.getItem(KEY))||{schema:'HOOKLAB_CORPUS_STAT_STORE_v0.1',cases:[]}}catch(e){return{schema:'HOOKLAB_CORPUS_STAT_STORE_v0.1',cases:[]}}}function save(s){localStorage.setItem(KEY,JSON.stringify(s));return s}function add(pkg){if(!pkg||!pkg.case_id)throw Error('CASE_ID_REQUIRED');if(!pkg.features||!pkg.evidence)throw Error('FEATURE_PACKAGE_REQUIRED');var s=load(),i=s.cases.findIndex(x=>x.case_id===pkg.case_id);var row={case_id:pkg.case_id,source_provenance:pkg.source_provenance||null,engine_provenance:pkg.engine_provenance||null,features:pkg.features,evidence:pkg.evidence,scientific_state:pkg.scientific_state||'NOT_YET_ADMITTED',added_at:new Date().toISOString()};if(i>=0)s.cases[i]=row;else s.cases.push(row);return save(s)}function clear(){return save({schema:'HOOKLAB_CORPUS_STAT_STORE_v0.1',cases:[]})}function exportStore(){return load()}g.HookLabCorpusStore={version:'0.1',load:load,add:add,clear:clear,exportStore:exportStore}})(window);